// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address _target, uint256 _value, bytes calldata _data) public {
        vm.assume(_value <= address(this).balance);
        vm.deal(address(this), _value);
        bool ok;
        try c.sendMoney(_target, _value, _data) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
